        case "task:log": self = .taskLog(try TaskLogEvent(from: decoder))
        case "task:created": self = .taskCreated(try TaskCreatedEvent(from: decoder))
        case "task:pending_reason": self = .taskPendingReason(try TaskPendingReasonEvent(from: decoder))
        case "task:stalled": self = .taskStalled(try TaskStalledEvent(from: decoder))
        case "task:recovered": self = .taskRecovered(try TaskRecoveredEvent(from: decoder))
        case "auth:failed": self = .authFailed(try AuthFailedEvent(from: decoder))
        case "auth:status_changed": self = .authStatusChanged(try AuthStatusChangedEvent(from: decoder))
        case "session:created": self = .sessionCreated(try SessionCreatedEvent(from: decoder))
        case "session:ended": self = .sessionEnded(try SessionEndedEvent(from: decoder))
        case "task:comment": self = .taskComment(try TaskCommentEvent(from: decoder))
        case "task:message": self = .taskMessage(try TaskMessageEvent(from: decoder))
        case "task:message_delivered", "task:message_acked": self = .taskMessageDelivered(try TaskMessageDeliveredEvent(from: decoder))
        case "workflow_run:state_changed": self = .workflowRunStateChanged(try WorkflowRunStateChangedEvent(from: decoder))
        case "workflow_run:log": self = .workflowRunLog(try WorkflowRunLogEvent(from: decoder))
        case "pr_review:state_changed": self = .prReviewStateChanged(try PrReviewStateChangedEvent(from: decoder))
        case "pr_review_run:state_changed": self = .prReviewRunStateChanged(try PrReviewRunStateChangedEvent(from: decoder))
        case "pr_review_run:log": self = .prReviewRunLog(try PrReviewRunLogEvent(from: decoder))
        case "pr_review:stale": self = .prReviewStale(try PrReviewStaleEvent(from: decoder))
        case "activity:new": self = .activityNew(try ActivityNewEvent(from: decoder))
        case "persistent_agent:state_changed": self = .persistentAgentStateChanged(try PersistentAgentStateChangedEvent(from: decoder))
        case "persistent_agent:turn_started": self = .persistentAgentTurnStarted(try PersistentAgentTurnStartedEvent(from: decoder))
