/// What happens once an agent finishes its first turn.
/// - `interactive`: the agent halts at its prompt and waits for you (the
/// session lands in the "needs you" queue; you can chat with it).
/// - `headless`: the agent runs in one-shot / print mode and the process exits
/// when the turn is done. The transcript is kept, so the session can still be
/// resumed into an interactive chat later.
public enum LocalAgentSessionMode: String, Codable, Hashable, Sendable, CaseIterable {
    case interactive = "interactive"
    case headless = "headless"
    /// Fallback for raw values this client does not know about yet.
    case unknown = "__unknown__"

    public static let allCases: [LocalAgentSessionMode] = [.interactive, .headless]

    public init(from decoder: any Decoder) throws {
        let raw = try decoder.singleValueContainer().decode(String.self)
        self = LocalAgentSessionMode(rawValue: raw) ?? .unknown
    }
}

/// How the daemon should build the process for a terminal.
public enum LocalTerminalSpec: Codable, Hashable, Sendable {
    case shell
    case command(CommandPayload)
    case agent(AgentPayload)
    /// Fallback for discriminator values this client does not know about yet.
    case unknown(AnyCodable)

    public struct CommandPayload: Codable, Hashable, Sendable {
        public let command: String

        private enum CodingKeys: String, CodingKey {
            case command = "command"
        }

        public init(command: String) {
            self.command = command
        }
    }

    public struct AgentPayload: Codable, Hashable, Sendable {
        public let agent: LocalAgentKind
        public let prompt: String?
        /// Default `interactive`.
        public let mode: LocalAgentSessionMode?
        /// Resume a previous agent session (its id as reported by the agent's
        /// hooks) instead of starting a fresh one. Interactive unless the agent
        /// supports a headless resume (Claude Code: `claude -p --resume`).
        public let resumeSessionId: String?
        /// Model override passed to the agent CLI (`--model` / `-m`), when set.
        public let model: String?

        private enum CodingKeys: String, CodingKey {
            case agent = "agent"
            case prompt = "prompt"
            case mode = "mode"
            case resumeSessionId = "resumeSessionId"
            case model = "model"
        }

        public init(
            agent: LocalAgentKind,
            prompt: String? = nil,
            mode: LocalAgentSessionMode? = nil,
            resumeSessionId: String? = nil,
            model: String? = nil
        ) {
            self.agent = agent
            self.prompt = prompt
            self.mode = mode
            self.resumeSessionId = resumeSessionId
            self.model = model
        }
    }

    private enum DiscriminatorKey: String, CodingKey {
        case kind
    }

    public init(from decoder: any Decoder) throws {
        let container = try decoder.container(keyedBy: DiscriminatorKey.self)
        let discriminator = try container.decodeIfPresent(String.self, forKey: .kind) ?? ""
        switch discriminator {
        case "shell": self = .shell
        case "command": self = .command(try CommandPayload(from: decoder))
        case "agent": self = .agent(try AgentPayload(from: decoder))
        default: self = .unknown(try AnyCodable(from: decoder))
        }
    }

    public func encode(to encoder: any Encoder) throws {
        switch self {
        case .shell:
            var container = encoder.container(keyedBy: DiscriminatorKey.self)
            try container.encode("shell", forKey: .kind)
        case .command(let payload):
            var container = encoder.container(keyedBy: DiscriminatorKey.self)
            try container.encode("command", forKey: .kind)
            try payload.encode(to: encoder)
        case .agent(let payload):
            var container = encoder.container(keyedBy: DiscriminatorKey.self)
            try container.encode("agent", forKey: .kind)
            try payload.encode(to: encoder)
        case .unknown(let value):
            try value.encode(to: encoder)
        }
    }
}

